-- 0043 · TẦNG TUÂN THỦ theo SPEC-05: chuẩn = metadata gắn lên hệ sẵn có · CONTROL = vật thật trong app (trigger/alert/checklist/report/field/process/test) có evidence_query · điều khoản không trỏ được control = GAP đỏ · gói audit theo chuẩn = bộ lọc export
-- ===== chuẩn bổ sung theo SPEC-05 (giữ mã hiện có, thêm alias spec) =====
alter table standards add column if not exists spec_code text, add column if not exists priority int;
update standards set spec_code = case code when 'VIETGAP-TT' then 'VN-VIETGAP-TT' when 'VIETGAP-CN' then 'VN-VIETGAP-CN' when 'ORGANIC-VN' then 'VN-ORG' when 'HACCP' then 'CODEX-HACCP' when 'ISO22000' then 'ISO-22000' when 'ISO9001' then 'ISO-9001' when 'GLOBALGAP' then 'GGAP-IFA' when 'EU-ORGANIC' then 'EU-ORG' when 'USDA-NOP' then 'US-NOP' when 'HALAL' then 'HALAL' when 'JAS-ORGANIC' then 'JP-GAP' when 'KR-MFDS' then 'KR-CERT' else code end;
on conflict (code) do update set spec_code=excluded.spec_code, priority=excluded.priority, description=excluded.description;
update standards set priority = case when code in ('VIETGAP-TT','VIETGAP-CN','ITRAN-STD') then 1 when code in ('HACCP','ISO22000') then 2 when code in ('ORGANIC-VN','EU-ORGANIC') then 3 else coalesce(priority,4) end where priority is null;
-- ===== CONTROLS: vật thật trong app =====
create table if not exists controls(id text primary key, kind text not null, -- TRIGGER|ALERT|CHECKLIST|REPORT|FIELD|PROCESS|TEST|VIEW|JOB
  ref text not null, description text, evidence_query text, owner_dept text, active bool default true);
create table if not exists clause_controls(requirement_id int references standard_requirements on delete cascade, control_id text references controls on delete cascade, primary key(requirement_id, control_id));
create table if not exists compliance_gaps(id uuid primary key default gen_random_uuid(), requirement_id int references standard_requirements, farm_id text, status text default 'MO', -- MO|DANG_LAM|DONG
  plan text, due date, owner text, created_at timestamptz default now(), closed_at timestamptz);
do $$ declare t text; begin foreach t in array array['controls','clause_controls','compliance_gaps'] loop execute format('alter table %I enable row level security', t); execute format('drop policy if exists p_all on %I', t); execute format('create policy p_all on %I for all using (true) with check (app_role() in (''owner'',''director'',''it_engineer'',''tech_head'',''auditor''))', t); execute format('grant select, insert, update, delete on %I to app_user', t); end loop; end $$;
on conflict (id) do update set kind=excluded.kind, ref=excluded.ref, description=excluded.description, evidence_query=excluded.evidence_query, owner_dept=excluded.owner_dept;
-- ===== Điều khoản TT66 / NĐ13 / Phân bón (tóm tắt để lập ma trận) =====
on conflict (standard_code, clause) do update set title=excluded.title, evidence_tables=excluded.evidence_tables, process_codes=excluded.process_codes;
-- ===== Map điều khoản → control (theo nhóm §3 SPEC-05) =====
select r.id, m.control from standard_requirements r join (values
 ('%truy xuất%','C-TRACE'),('%thu hồi%','C-RECALL'),('%CCP%','C-CCP'),('%HACCP%','C-CCP'),('%ngưng thuốc%','C-WITHDRAWAL'),('%thuốc%','C-MEDBOOK'),('%vaccine%','C-MEDBOOK'),('%Sổ theo dõi đàn%','C-TT66'),('%báo cáo%','C-TT66'),
 ('%COA%','C-COA'),('%NCC%','C-COA'),('%nhà cung cấp%','C-COA'),('%Phân bón%','C-CROPLOG'),('%BVTV%','C-CROPLOG'),('%Nhật ký%','C-CROPLOG'),('%nước%','C-WATERTEST'),('%đất%','C-WATERTEST'),
 ('%vệ sinh%','C-SANITATION'),('%Vệ sinh%','C-SANITATION'),('%đào tạo%','C-TRAINING'),('%Người lao động%','C-TRAINING'),('%Nhân sự%','C-TRAINING'),('%hiệu chuẩn%','C-CALIB'),('%thiết bị%','C-CALIB'),
 ('%lưu mẫu%','C-SAMPLE'),('%tài liệu%','C-DOCCTRL'),('%văn bản%','C-DOCCTRL'),('%audit%','C-AUDIT'),('%Đánh giá%','C-AUDIT'),('%kiểm tra nội bộ%','C-AUDIT'),('%khắc phục%','C-CAPA'),('%không phù hợp%','C-CAPA'),
 ('%cách ly%','C-QUARANTINE'),('%ATSH%','C-QUARANTINE'),('%sinh học%','C-QUARANTINE'),('%phúc lợi%','C-WELFARE'),('%mật độ%','C-WELFARE'),('%môi trường%','C-ENV'),('%chất thải%','C-ENV'),('%nước thải%','C-ENV'),
 ('%hữu cơ%','C-ORGANIC'),('%Chuyển đổi%','C-ORGANIC'),('%Annex%','C-ORGANIC'),('%National List%','C-ORGANIC'),('%Halal%','C-HALAL'),('%haram%','C-HALAL'),('%dữ liệu cá nhân%','C-PDPA'),('%consent%','C-PDPA'),
 ('%QCVN 01-189%','C-FERT'),('%lưu hành%','C-FERT'),('%Cổng%','C-GATE'),('%kiểm dịch%','C-GATE'),('%append%','C-APPENDONLY'),('%ghi chép%','C-APPENDONLY'),('%Ghi chép%','C-APPENDONLY'),('%hồ sơ%','C-APPENDONLY'),('%Hồ sơ%','C-APPENDONLY'),('%Sổ sách%','C-APPENDONLY'),('%truy được%','C-TRACE'),('%dư lượng%','C-CROPLOG'),('%MRL%','C-CROPLOG'),('%PHI%','C-CROPLOG'),('%giống%','C-QUARANTINE'),('%Con giống%','C-QUARANTINE'),('%thức ăn%','C-ORGANIC'),('%Thức ăn%','C-MEDBOOK'),('%kháng sinh%','C-MEDBOOK'),('%Sức khỏe%','C-MEDBOOK'),('%Điều hành%','C-AUDIT'),('%Bối cảnh%','C-DOCCTRL'),('%Hỗ trợ%','C-TRAINING'),('%PRP%','C-SANITATION'),('%Kiểm soát sản phẩm%','C-CCP'),('%Nhân sự%','C-TRAINING'),('%Xã hội%','C-TRAINING'),('%lao động%','C-TRAINING'),('%pháp luật%','C-DOCCTRL'),('%vùng trồng%','C-CROPLOG'),('%GACC%','C-TRACE'),('%Grader%','C-DOCCTRL'),('%grader%','C-DOCCTRL'),('%OSP%','C-DOCCTRL'),('%lưu hồ sơ%','C-APPENDONLY'),('%Lưu hồ sơ%','C-APPENDONLY'),('%Cam kết%','C-AUDIT'),('%Truy xuất%','C-TRACE'),('%rủi ro%','C-CAPA'),('%Kế hoạch%','C-DOCCTRL')
) m(pat, control) on r.title ilike m.pat or coalesce(r.requirement,'') ilike m.pat
where r.standard_code<>'ITRAN-STD' on conflict do nothing;
-- ITRAN-STD: mọi điều đều có control = chính metric_sql (C-ICFS) + control theo nhóm
-- ===== Độ phủ + GAP tự sinh =====
create or replace view v_compliance_coverage as
select s.code as standard_code, s.name, s.priority, s.spec_code, count(r.id) as clauses,
  count(r.id) filter (where exists (select 1 from clause_controls cc where cc.requirement_id=r.id)) as with_control,
  count(r.id) filter (where r.level in ('CRITICAL','MAJOR')) as major, count(r.id) filter (where r.level in ('CRITICAL','MAJOR') and exists (select 1 from clause_controls cc where cc.requirement_id=r.id)) as major_with_control,
  round(100.0*count(r.id) filter (where exists (select 1 from clause_controls cc where cc.requirement_id=r.id))/nullif(count(r.id),0),0) as pct
from standards s left join standard_requirements r on r.standard_code=s.code where s.active group by s.code, s.name, s.priority, s.spec_code order by s.priority, s.code;
grant select on v_compliance_coverage to app_user;
create or replace function refresh_compliance_gaps() returns int language plpgsql as $$
declare n int; begin
  update compliance_gaps g set status='DONG', closed_at=now() where status<>'DONG' and exists (select 1 from clause_controls cc where cc.requirement_id=g.requirement_id);
  get diagnostics n = row_count; return n; end $$;
select refresh_compliance_gaps();
grant execute on function refresh_compliance_gaps() to app_user;
-- ===== Audit nội bộ 2 lần/năm & diễn tập thu hồi 2 lần/năm: việc tự sinh (job tasks) =====
create or replace function gen_compliance_tasks(p_farm text) returns int language plpgsql as $$
declare n int := 0; half text := to_char(now(),'YYYY')||'-H'||case when extract(month from now())<=6 then 1 else 2 end; begin
  if not exists (select 1 from tasks where farm_id=p_farm and kind='AUDIT_NOI_BO' and detail->>'period'=half) then insert into tasks(farm_id,kind,title,detail,role_hint,priority,due_at,source) values (p_farm,'AUDIT_NOI_BO','Audit nội bộ '||half||' — tự đánh giá điều khoản (chuẩn ưu tiên 1–2) tại /tuan-thu', jsonb_build_object('period',half,'link','/tuan-thu'),'auditor','CAO', date_trunc('quarter', now()) + interval '2 months', 'COMPLIANCE'); n:=n+1; end if;
  if not exists (select 1 from tasks where farm_id=p_farm and kind='DIEN_TAP_THU_HOI' and detail->>'period'=half) then insert into tasks(farm_id,kind,title,detail,role_hint,priority,due_at,source) values (p_farm,'DIEN_TAP_THU_HOI','Diễn tập thu hồi lô ≤4h '||half||' — chọn 1 lô, truy 1 lùi 1 tiến, biên bản', jsonb_build_object('period',half,'link','/truy-xuat'),'tech_head','CAO', date_trunc('quarter', now()) + interval '2 months', 'COMPLIANCE'); n:=n+1; end if;
  return n; end $$;
grant execute on function gen_compliance_tasks(text) to app_user;
select gen_compliance_tasks(id) from farms where status='ACTIVE';
