insert into standards(code,name,issuer,scope,region,description,required_for,position,url,spec_code,priority) values
('VN-TT66','Thông tư 66/2025/TT-BNNMT — hồ sơ, sổ sách chăn nuôi (kê khai, sổ đàn, sổ thuốc, báo cáo định kỳ)','Bộ NN&MT','CHAN_NUOI','VN','Bắt buộc pháp lý với cơ sở chăn nuôi: kê khai, sổ theo dõi đàn/thuốc/thức ăn/dịch bệnh, báo cáo cơ quan','{PHAP_LY}',0,'Văn bản TT 66/2025 (đối chiếu bản gốc)','VN-TT66',1),
('VN-ND13','Nghị định 13/2023/NĐ-CP — bảo vệ dữ liệu cá nhân','Chính phủ','QUAN_LY','VN','Consent, quyền chủ thể dữ liệu (xem/sửa/xóa), thông báo vi phạm 72h, hồ sơ xử lý dữ liệu','{PHAP_LY}',0,'https://vanban.chinhphu.vn (NĐ 13/2023)','VN-ND13',1),
('VN-PHANBON','Luật Trồng trọt + NĐ 84/2019 + QCVN 01-189:2019 — phân bón','Bộ NN&PTNT','TRONG_TROT','VN','Phân bón lưu hành phải được công nhận, kiểm nghiệm từng lô đạt QCVN trước xuất bán (làn 2 phân trùn/compost)','{PHAP_LY,BAN_PHAN}',0,'QCVN 01-189:2019/BNNPTNT','VN-PHANBON',1),
('JGAP','JGAP / ASIAGAP (Nhật, tương thích GFSI)','Japan GAP Foundation','TRONG_TROT','JP','GAP Nhật cho xuất khẩu; ASIAGAP được GFSI công nhận','{XUAT_KHAU_NHAT}',20,'https://jgap.jp','JP-GAP',3)
insert into controls(id,kind,ref,description,evidence_query,owner_dept) values
('C-TRACE','VIEW','v_trace_links + /trace/{lot} + EPCIS export','Truy xuất 1 bước lùi – 1 bước tiến: mẻ inputs/outputs, tem mã mẻ, trang công khai','select count(*) as lots_traced from lots l where farm_id=$1 and exists (select 1 from inventory_moves m where m.lot_id=l.id)','QA'),
('C-CCP','FIELD','batch_logs.ccp_readings + sops.ccp + AL-CCP + INCIDENT','Giám sát CCP, giới hạn tới hạn, hành động khắc phục; ĐỎ dừng chuyền','select count(*) as batches_with_ccp from batch_logs where farm_id=$1 and status=''ACTIVE'' and ccp_readings is not null and ts>now()-interval ''90 days''','D5'),
('C-RECALL','PROCESS','P-QA-02 truy xuất & thu hồi + mock recall 2 lần/năm (tasks)','Thu hồi + diễn tập ≤4h có biên bản','select count(*) as recall_drills from tasks where farm_id=$1 and kind=''DIEN_TAP_THU_HOI'' and status=''XONG'' and done_at>now()-interval ''365 days''','QA'),
('C-WITHDRAWAL','TRIGGER','trigger chặn sales khi animals.withdrawal_until > now (ERR_WITHDRAWAL_ACTIVE)','Ngưng thuốc trước xuất — chặn cứng tầng DB','select count(*) as violations from sales s join animals a on a.id=s.detail->>''animal_id'' where s.farm_id=$1 and a.withdrawal_until>s.ts::date','KTCN'),
('C-MEDBOOK','REPORT','/api/exports/medicine-book + animal_events(DIEU_TRI/VACCINE) + treatment_protocols','Sổ thuốc – đơn thú y – vaccine (TT66, GGAP)','select count(*) as treatments_90d from animal_events where farm_id=$1 and status=''ACTIVE'' and event_type in (''DIEU_TRI'',''VACCINE'') and ts>now()-interval ''90 days''','KTCN'),
('C-TT66','REPORT','/api/exports/tt66 (sổ đàn, sổ thuốc, sổ thức ăn, dịch bệnh theo biểu mẫu)','Hồ sơ chăn nuôi định kỳ nộp cơ quan','select count(*) as animals_active from animals where farm_id=$1 and status not in (''CHET'',''XUAT'',''LOAI'')','KTCN'),
('C-COA','FIELD','partners.approved + lots.coa_url + documents(kind=COA); luật K1 chặn nhập thiếu COA','Vật tư đầu vào có COA / NCC phê duyệt','select count(*) filter (where p.approved) as approved, count(*) as total from partners p where (p.farm_id=$1 or p.farm_id is null) and p.kind in (''NCC'',''KH_NCC'')','CCU'),
('C-CROPLOG','FIELD','crop_logs (giống-lô, PHI safe_after, water_source) + crop_inputs + trigger PHI chặn thu hoạch + khóa backdate','Nhật ký đồng ruộng đầy đủ, PHI, nguồn nước','select count(*) as inputs_90d, count(*) filter (where organic_allowed is false) as not_allowed from crop_inputs where farm_id=$1 and status=''ACTIVE'' and ts>now()-interval ''90 days''','TT'),
('C-WATERTEST','TEST','lab_samples kind NUOC/DAT 2 lần/năm + task lịch','Test nước/đất định kỳ có kết quả','select count(*) as tests_365d from lab_samples where farm_id=$1 and kind in (''NUOC'',''DAT'') and taken_at>now()-interval ''365 days''','TT'),
('C-SANITATION','CHECKLIST','checklist_runs vệ sinh/khử trùng + BATCH anolyte (ppm mỗi mẻ)','Vệ sinh – khử trùng có log','select count(*) as checklists_30d from checklist_runs where farm_id=$1 and status=''ACTIVE'' and ts>now()-interval ''30 days''','KTCN'),
('C-TRAINING','FIELD','staff.sop_certs + positions_catalog.sops + chặn phân ca việc chưa chứng chỉ','Đào tạo – chứng chỉ trước khi làm','select count(*) filter (where sop_certs is not null and sop_certs::text<>''[]'') as certified, count(*) as total from staff where active and (farm_id=$1 or $1=any(farm_ids))','HCNS'),
('C-CALIB','ALERT','calibrations + devices.calib_due + AL đến hạn + cờ dữ liệu quá hạn hiệu chuẩn','Hiệu chuẩn thiết bị đo','select count(*) filter (where calib_due<current_date) as overdue, count(*) as total from devices where farm_id=$1 and calib_due is not null','CNTB'),
('C-SAMPLE','CHECKLIST','checklist lưu mẫu 24h (bếp) / 15 ngày (chế biến) + log tủ mẫu','Lưu mẫu thực phẩm','select count(*) as sample_logs_30d from checklist_runs where farm_id=$1 and sop_code ilike ''%LUU-MAU%'' and ts>now()-interval ''30 days''','D5'),
('C-DOCCTRL','FIELD','sops.version + published_at/by + xác nhận đọc-hiểu (staff.sop_certs) + audit_log','Kiểm soát tài liệu – phiên bản – đọc hiểu (ISO 9001:7.5)','select count(*) filter (where published_at is not null) as published, count(*) as total from sops','QA'),
('C-AUDIT','PROCESS','P-QA-01 + compliance_checks (tự đánh giá 2 lần/năm) + xem xét lãnh đạo (report pl-thang)','Đánh giá nội bộ + xem xét lãnh đạo (ISO 9001:9)','select count(*) as checks_365d from compliance_checks where farm_id=$1 and checked_at>now()-interval ''365 days''','QA'),
('C-CAPA','FIELD','incidents.five_why + capa + closed_at ≤7 ngày; sops v+1','Hành động khắc phục – CAPA (ISO 9001:10)','select count(*) filter (where closed_at is not null) as closed, count(*) as total from incidents where farm_id=$1 and status=''ACTIVE'' and ts>now()-interval ''365 days''','QA'),
('C-QUARANTINE','FIELD','intake_lots.quarantine_until + CACH_LY_VAO/RA + SOP-BO-01 + gate_logs anolyte_wash','Cách ly nhập đàn – an toàn sinh học','select count(*) filter (where anolyte_wash) as washed, count(*) as total from gate_logs where farm_id=$1 and status=''ACTIVE'' and ts>now()-interval ''30 days''','KTCN'),
('C-WELFARE','FIELD','locations.capacity + settings mật độ + checklist ca + SOP phúc lợi','Phúc lợi: mật độ, nước tự do, không cắt mỏ','select count(*) as over_capacity from v_location_summary where farm_id=$1 and capacity is not null and coalesce(head_count,head,0) > capacity','KTCN'),
('C-ENV','VIEW','RC13 nước + sensor_reads nước thải + batch_logs biogas/compost + SOP wetland','Môi trường: zero xả, nước rỉ ủ phân gom xử lý','select count(*) as env_readings_30d from sensor_reads where farm_id=$1 and metric in (''water_m3'',''biogas_m3'',''cod'',''ph_out'') and ts>now()-interval ''30 days''','SH'),
('C-ORGANIC','VIEW','lots.organic/crop_inputs.organic_allowed + plots.organic_since/crop_seasons.conversion_stage + view % khẩu phần hữu cơ + cảnh báo trộn làn','Hữu cơ: % thức ăn hữu cơ, cấm GMO, đồng hồ chuyển đổi, tách khu','select count(*) filter (where conversion_stage is not null) as organic_seasons, count(*) as total from crop_seasons where farm_id=$1','TT'),
('C-HALAL','FIELD','recipes.halal_ok + recipes.no_bsf + hợp đồng lò mổ (documents) + cờ dòng SKU (products.halal_ok)','Halal: recipe không-BSF, lò mổ chứng nhận, tách dòng','select count(*) filter (where halal_ok) as halal_recipes, count(*) as total from recipes where farm_id=$1 and active','D5'),
('C-PDPA','FIELD','partners.consent + custody consent_at + job ẩn danh 5 năm + runbook sự cố 72h','Dữ liệu cá nhân NĐ13: consent, quyền xóa, thông báo 72h','select count(*) filter (where consent is not null) as consented, count(*) as total from partners where (farm_id=$1 or farm_id is null) and kind like ''KH%''','KDM'),
('C-FERT','TRIGGER','lots phân (SKU-PTR/compost) + lab_samples đạt QCVN + chặn xuất K5-phân khi thiếu phiếu lab','Phân bón: kiểm nghiệm từng lô đạt QCVN trước xuất','select count(*) as fert_lots from lots where farm_id=$1 and sku like ''SKU-PTR%''','SH'),
('C-GATE','FIELD','gate_logs 100% xe + weigh_tickets + anolyte','Cổng sinh học – cân – rửa xe','select count(*) as gate_30d from gate_logs where farm_id=$1 and status=''ACTIVE'' and ts>now()-interval ''30 days''','CCU'),
('C-APPENDONLY','TRIGGER','itran_no_update_delete + supersede + audit_log + gói audit sha256','Bằng chứng = dữ liệu vận hành append-only','select count(*) as events_30d from audit_log where ts>now()-interval ''30 days''','CNTB'),
('C-ICFS','JOB','icfs_score() + /chuan công khai','Chuẩn ITRAN tự chấm từ dữ liệu','select pct, level from v_icfs_summary where farm_id=$1','QA')
insert into standard_requirements(standard_code,clause,title,requirement,level,evidence_tables,evidence_records,process_codes,frequency,owner_dept) values
('VN-TT66','1','Kê khai hoạt động chăn nuôi với UBND xã (loại, quy mô, địa điểm)','Kê khai & cập nhật khi thay đổi quy mô','CRITICAL','{farms,animal_groups,herd_daily}','{HS-SO-DAN}','{P-VN-01}','Khi thay đổi','GDT'),
('VN-TT66','2','Sổ theo dõi đàn: nhập, xuất, sinh, chết, chuyển','Ghi hằng ngày theo cá thể/đàn','CRITICAL','{animals,animal_events,intake_lots}','{HS-SO-DAN}','{SOP-BO-01,SOP-BO-09,P-VN-07}','Ngày','KTCN'),
('VN-TT66','3','Sổ theo dõi thức ăn, nguyên liệu, nguồn gốc','FEED_LOG + lô nguyên liệu','MAJOR','{feed_logs,inventory_moves,recipes}','{HS-THUC-AN}','{SOP-BO-07,SOP-SH-05}','Ngày','D5'),
('VN-TT66','4','Sổ theo dõi thuốc thú y, vaccine, ngưng thuốc','Đơn thú y, lô thuốc, liều, ngưng thuốc','CRITICAL','{animal_events,treatment_protocols}','{HS-THU-Y}','{SOP-BO-08}','Mỗi lần','KTCN'),
('VN-TT66','5','Sổ theo dõi dịch bệnh & xử lý xác/chất thải','Bệnh, chết, xử lý theo quy định','MAJOR','{animal_events,incidents,batch_logs}','{HS-THU-Y,HS-MOI-TRUONG}','{SOP-AT-06,P-VN-07}','Mỗi lần','KTCN'),
('VN-TT66','6','Báo cáo định kỳ/đột xuất cho cơ quan quản lý','Xuất biểu mẫu TT66 1 nút','MAJOR','{agg_daily}','{HS-SO-DAN}','{P-QT-02}','Quý','GDT'),
('VN-ND13','1','Thu thập dữ liệu cá nhân có sự đồng ý (consent) rõ mục đích','partners.consent, custody consent_at, khách lưu trú','CRITICAL','{partners,custody_contracts,hosp_bookings}','{HS-NHAN-NUOI,HS-DU-LICH}','{SOP-KD-03,SOP-RS-01}','Mỗi lần','KDM'),
('VN-ND13','2','Quyền chủ thể: xem, sửa, xóa/ẩn danh theo yêu cầu','Job ẩn danh, quy trình xử lý yêu cầu','MAJOR','{partners,audit_log}','{HS-AUDIT}','{P-CN-02}','Mỗi yêu cầu','CNTB'),
('VN-ND13','3','Bảo mật & thông báo vi phạm trong 72h','Runbook sự cố dữ liệu, incident','MAJOR','{incidents}','{HS-AUDIT}','{P-QT-01}','Sự kiện','CNTB'),
('VN-ND13','4','Hồ sơ đánh giá tác động xử lý dữ liệu, lưu ≥5 năm','Tài liệu đánh giá, lưu documents','MINOR','{documents}','{HS-PHAP-LY}','{SOP-HC-04}','Năm','HCNS'),
('VN-PHANBON','1','Phân bón lưu hành phải được công nhận (Quyết định công nhận)','Hồ sơ công nhận sản phẩm phân trùn/compost','CRITICAL','{products,documents}','{HS-PHAP-LY}','{SOP-HC-04}','Khi lưu hành','SH'),
('VN-PHANBON','2','Kiểm nghiệm từng lô đạt QCVN 01-189 trước xuất bán','lab_samples theo lô; chặn xuất K5-phân thiếu phiếu','CRITICAL','{lots,lab_samples,inventory_moves}','{HS-TRUY-XUAT}','{SOP-SH-01,SOP-SH-04}','Mỗi lô','SH'),
('VN-PHANBON','3','Nhãn, bao bì, công bố hợp quy','Nhãn đúng quy định','MAJOR','{products,lots}','{HS-TRUY-XUAT}','{SOP-CB-05}','Mỗi lô','D5'),
('JGAP','1','Quản lý trại & hồ sơ, an toàn lao động, môi trường (khung ASIAGAP/GFSI)','Tương đương GlobalG.A.P. AF/CB','MAJOR','{documents,staff,crop_seasons}','{HS-CANH-TAC}','{P-QA-01}','Năm','QA'),
('JGAP','2','ATTP: dư lượng, nước, vệ sinh thu hoạch','MRL Nhật, phân tích trước xuất','CRITICAL','{crop_inputs,lab_samples,harvests}','{HS-CANH-TAC}','{SOP-TT-02,SOP-TT-03}','Vụ','TT')
insert into clause_controls(requirement_id, control_id)
insert into clause_controls(requirement_id, control_id) select id, 'C-ICFS' from standard_requirements where standard_code='ITRAN-STD' on conflict do nothing;
  insert into compliance_gaps(requirement_id, farm_id, status, plan) select r.id, null, 'MO', 'Chưa có control trong app — cần thêm bảng/trigger/checklist/report hoặc map control có sẵn' from standard_requirements r where not exists (select 1 from clause_controls cc where cc.requirement_id=r.id) and not exists (select 1 from compliance_gaps g where g.requirement_id=r.id and g.status<>'DONG');
